"use client";

import { Send } from "lucide-react";
import { motion } from "framer-motion";
import { useState } from "react";

export const Newsletter = () => {
    const [email, setEmail] = useState("");
    const [status, setStatus] = useState<"idle" | "loading" | "success">("idle");

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setStatus("loading");
        setTimeout(() => {
            setStatus("success");
            setEmail("");
            setTimeout(() => setStatus("idle"), 5000);
        }, 1500);
    };

    return (
        <section className="py-20 relative overflow-hidden">
            {/* Background Gradients */}
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[400px] bg-primary/20 blur-[120px] rounded-full pointer-events-none" />

            <div className="container mx-auto px-6 relative z-10">
                <div className="max-w-5xl mx-auto glass rounded-[3rem] p-12 md:p-20 text-center relative overflow-hidden">
                    {/* Subtle decoration */}
                    <div className="absolute top-0 right-0 w-64 h-64 bg-primary/10 blur-[80px] rounded-full -mr-20 -mt-20" />

                    <h2 className="text-4xl md:text-6xl font-black uppercase tracking-tighter mb-6 leading-tight">
                        Never miss a <span className="text-primary italic">Chapter</span>
                    </h2>
                    <p className="text-lg text-muted-foreground mb-12 max-w-2xl mx-auto">
                        Subscribe to our newsletter to get weekly summaries, exclusive original novel previews, and early access to events.
                    </p>

                    {status === "success" ? (
                        <motion.div
                            initial={{ scale: 0.9, opacity: 0 }}
                            animate={{ scale: 1, opacity: 1 }}
                            className="bg-primary/20 border border-primary/30 p-8 rounded-3xl max-w-xl mx-auto"
                        >
                            <h3 className="text-2xl font-bold text-white mb-2">Welcome to the inner circle! 🚀</h3>
                            <p className="text-white/60">Check your inbox to confirm your subscription.</p>
                        </motion.div>
                    ) : (
                        <form className="flex flex-col sm:flex-row gap-4 max-w-xl mx-auto" onSubmit={handleSubmit}>
                            <input
                                type="email"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                required
                                placeholder="yourname@email.com"
                                className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-8 py-4 text-white placeholder:text-white/30 focus:outline-none focus:ring-2 focus:ring-primary/50 transition-all font-medium"
                            />
                            <button
                                type="submit"
                                disabled={status === "loading"}
                                className="px-10 py-4 bg-primary hover:bg-primary/90 text-white font-bold rounded-2xl shadow-[0_10px_30px_rgba(124,58,237,0.3)] hover:scale-105 transition-all flex items-center justify-center gap-3 uppercase tracking-wider disabled:opacity-50 disabled:hover:scale-100 italic"
                            >
                                {status === "loading" ? "Joining..." : "Subscribe Now"}
                                <Send size={18} />
                            </button>
                        </form>
                    )}
                </div>
            </div>
        </section>
    );
};

export default Newsletter;
