"use client";

import { useState, useEffect } from "react";
import { Search, User, Menu, X, Crown } from "lucide-react";
import Link from "next/link";
import { motion, AnimatePresence } from "framer-motion";

const Navbar = () => {
    const [isOpen, setIsOpen] = useState(false);
    const [scrolled, setScrolled] = useState(false);
    const [user, setUser] = useState<{ role: string } | null>(null);

    useEffect(() => {
        const handleScroll = () => {
            setScrolled(window.scrollY > 20);
        };
        window.addEventListener("scroll", handleScroll);

        const fetchUser = async () => {
            const token = localStorage.getItem("token");
            if (token) {
                try {
                    const res = await fetch("http://localhost:4000/api/auth/me", {
                        headers: { Authorization: `Bearer ${token}` }
                    });
                    if (res.ok) {
                        const data = await res.json();
                        setUser(data);
                    } else {
                        localStorage.removeItem("token");
                        setUser(null);
                    }
                } catch (e) {
                    console.error("Failed to fetch user in Navbar", e);
                    localStorage.removeItem("token");
                    setUser(null);
                }
            }
        };
        fetchUser();

        return () => window.removeEventListener("scroll", handleScroll);
    }, []);

    const navLinks = [
        { name: "Discovery", href: "/" },
        { name: "Novels", href: "/novels" },
        { name: "Originals", href: "/originals" },
        { name: "Community", href: "/community" },
    ];

    return (
        <nav
            className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${scrolled ? "bg-background/80 backdrop-blur-lg border-b border-white/10 py-3" : "bg-transparent py-5"
                }`}
        >
            <div className="container mx-auto px-6 flex items-center justify-between">
                {/* Logo */}
                <Link href="/" className="flex items-center gap-2 group">
                    <img
                        src="/img/lunoxscan_site_logo.png"
                        alt="LunoxScan Logo"
                        className="h-10 w-auto object-contain transition-transform duration-300 group-hover:scale-110"
                    />
                </Link>

                {/* Desktop Nav */}
                <div className="hidden md:flex items-center gap-8">
                    {navLinks.map((link) => (
                        <Link
                            key={link.name}
                            href={link.href}
                            className="text-sm font-medium text-white/70 hover:text-white transition-colors duration-200"
                        >
                            {link.name}
                        </Link>
                    ))}
                </div>

                {/* Actions */}
                <div className="hidden md:flex items-center gap-5">
                    <button className="p-2 text-white/70 hover:text-white transition-colors">
                        <Search size={22} />
                    </button>
                    {user?.role === 'admin' && (
                        <Link href="/admin/dashboard" className="px-5 py-2 glass hover:bg-white/10 rounded-full text-white text-sm font-semibold transition-all">
                            Admin
                        </Link>
                    )}
                    <Link href="/premium" className="px-5 py-2 bg-primary hover:bg-primary/90 rounded-full text-white text-sm font-semibold flex items-center gap-2 transition-all hover:scale-105 shadow-[0_0_20px_rgba(124,58,237,0.3)]">
                        <Crown size={16} />
                        Go Premium
                    </Link>
                    {user ? (
                        <div className="relative group">
                            <button className="w-10 h-10 rounded-full bg-primary/20 flex items-center justify-center hover:bg-primary/30 transition-all border border-primary/30">
                                <User size={20} className="text-primary" />
                            </button>
                            <div className="absolute right-0 mt-2 w-48 glass rounded-2xl p-2 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-300 transform origin-top-right group-hover:scale-100 scale-95 z-[60]">
                                <div className="px-4 py-3 border-b border-white/5 mb-2">
                                    <p className="text-xs text-white/50 uppercase tracking-widest font-bold">Account</p>
                                    <p className="text-sm font-medium truncate">{(user as any).username || 'Member'}</p>
                                </div>
                                <Link href="/profile" className="flex items-center gap-3 px-4 py-2 hover:bg-white/5 rounded-xl transition-colors text-sm">
                                    <User size={16} />
                                    Profile
                                </Link>
                                <button
                                    onClick={() => {
                                        localStorage.removeItem('token');
                                        window.location.href = '/auth';
                                    }}
                                    className="flex items-center gap-3 px-4 py-2 hover:bg-destructive/10 text-destructive rounded-xl transition-colors text-sm w-full text-left"
                                >
                                    <X size={16} />
                                    Logout
                                </button>
                            </div>
                        </div>
                    ) : (
                        <Link href="/auth" className="w-10 h-10 rounded-full bg-white/10 flex items-center justify-center hover:bg-white/20 transition-colors">
                            <User size={20} />
                        </Link>
                    )}
                </div>

                {/* Mobile Toggle */}
                <button className="md:hidden text-white" onClick={() => setIsOpen(!isOpen)}>
                    {isOpen ? <X size={28} /> : <Menu size={28} />}
                </button>
            </div>

            {/* Mobile Menu */}
            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ opacity: 0, y: -20 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -20 }}
                        className="md:hidden absolute top-full left-0 right-0 bg-secondary border-b border-white/10 p-6 flex flex-col gap-6"
                    >
                        {navLinks.map((link) => (
                            <Link
                                key={link.name}
                                href={link.href}
                                className="text-lg font-medium"
                                onClick={() => setIsOpen(false)}
                            >
                                {link.name}
                            </Link>
                        ))}
                        <div className="flex flex-col gap-4 pt-4 border-t border-white/5">
                            {user?.role === 'admin' && (
                                <Link
                                    href="/admin/dashboard"
                                    className="w-full py-3 border border-white/10 rounded-xl text-center font-bold"
                                    onClick={() => setIsOpen(false)}
                                >
                                    Admin Dashboard
                                </Link>
                            )}
                            <Link
                                href="/premium"
                                className="w-full py-3 bg-primary rounded-xl text-center font-bold"
                                onClick={() => setIsOpen(false)}
                            >
                                Go Premium
                            </Link>
                            {user ? (
                                <>
                                    <Link
                                        href="/profile"
                                        className="w-full py-3 bg-white/5 rounded-xl text-center font-medium"
                                        onClick={() => setIsOpen(false)}
                                    >
                                        Profile
                                    </Link>
                                    <button
                                        onClick={() => {
                                            localStorage.removeItem('token');
                                            window.location.href = '/auth';
                                        }}
                                        className="w-full py-3 bg-destructive/10 text-destructive rounded-xl text-center font-medium"
                                    >
                                        Logout
                                    </button>
                                </>
                            ) : (
                                <Link
                                    href="/auth"
                                    className="w-full py-3 bg-white/5 rounded-xl text-center font-medium"
                                    onClick={() => setIsOpen(false)}
                                >
                                    Login / Register
                                </Link>
                            )}
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </nav>
    );
};

export default Navbar;
